BEGIN TRANSACTION;
CREATE TABLE announcements(id INTEGER PRIMARY KEY,title TEXT,message TEXT,kind TEXT,created_by INTEGER,created_at TEXT,active INTEGER DEFAULT 1);
CREATE TABLE assets(id INTEGER PRIMARY KEY,name TEXT NOT NULL,asset_type TEXT,hostname TEXT,ip_address TEXT,service_id INTEGER,structure TEXT,location TEXT,owner_id INTEGER,criticality TEXT DEFAULT 'Medium',status TEXT DEFAULT 'Operational',notes TEXT,created_at TEXT);
CREATE TABLE audit(id INTEGER PRIMARY KEY,actor_id INTEGER,action TEXT,object_type TEXT,object_id INTEGER,old_value TEXT,new_value TEXT,ip TEXT,created_at TEXT);
CREATE TABLE board_lists(id INTEGER PRIMARY KEY,board_id INTEGER,name TEXT,pos INTEGER DEFAULT 0,is_done INTEGER DEFAULT 0);
CREATE TABLE boards(id INTEGER PRIMARY KEY,team_id INTEGER,name TEXT NOT NULL,owner_id INTEGER,created_at TEXT,archived INTEGER DEFAULT 0);
CREATE TABLE cards(id INTEGER PRIMARY KEY,board_id INTEGER,list_id INTEGER,title TEXT NOT NULL,description TEXT,assignee_id INTEGER,creator_id INTEGER,priority TEXT DEFAULT 'Medium',due_at TEXT,created_at TEXT,completed_at TEXT,pos INTEGER DEFAULT 0, source TEXT DEFAULT 'Personal Initiative', source_ref TEXT);
CREATE TABLE chat_messages(id INTEGER PRIMARY KEY,from_id INTEGER NOT NULL,to_id INTEGER NOT NULL,body TEXT NOT NULL,created_at TEXT,read_at TEXT);
CREATE TABLE email_log(id INTEGER PRIMARY KEY,to_addr TEXT,subject TEXT,ok INTEGER,message TEXT,created_at TEXT);
CREATE TABLE notifications(id INTEGER PRIMARY KEY,user_id INTEGER,title TEXT,message TEXT,link TEXT,kind TEXT DEFAULT 'info',is_read INTEGER DEFAULT 0,created_at TEXT);
CREATE TABLE org_units(id INTEGER PRIMARY KEY,parent_id INTEGER,name TEXT NOT NULL,kind TEXT DEFAULT 'SECTOR',sort INTEGER DEFAULT 0);
CREATE TABLE services(id INTEGER PRIMARY KEY,name TEXT UNIQUE,category TEXT,status TEXT DEFAULT 'Operational',owner_id INTEGER, parent_service_id INTEGER, is_main INTEGER DEFAULT 0, unit_id INTEGER);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT);
CREATE TABLE support_groups(id INTEGER PRIMARY KEY,name TEXT UNIQUE,description TEXT);
CREATE TABLE task_assignees(task_id INTEGER,user_id INTEGER,PRIMARY KEY(task_id,user_id));
CREATE TABLE task_events(id INTEGER PRIMARY KEY,task_id INTEGER,actor_id INTEGER,event_type TEXT,details TEXT,created_at TEXT);
CREATE TABLE tasks(id INTEGER PRIMARY KEY,ticket_id INTEGER,title TEXT,description TEXT,group_id INTEGER,priority TEXT,status TEXT DEFAULT 'Open',due_at TEXT,created_at TEXT,completed_at TEXT,completion_notes TEXT, parent_id INTEGER, created_by INTEGER, started_at TEXT);
CREATE TABLE team_members(team_id INTEGER,user_id INTEGER,role TEXT DEFAULT 'Member',added_at TEXT,PRIMARY KEY(team_id,user_id));
CREATE TABLE teams(id INTEGER PRIMARY KEY,name TEXT NOT NULL,description TEXT,color TEXT DEFAULT '#2f7cf6',owner_id INTEGER,created_at TEXT);
CREATE TABLE ticket_steps(id INTEGER PRIMARY KEY,ticket_id INTEGER,seq INTEGER,user_id INTEGER,instruction TEXT,status TEXT DEFAULT 'Pending',note TEXT,signed_by TEXT,signed_at TEXT,activated_at TEXT,created_at TEXT);
CREATE TABLE tickets(id INTEGER PRIMARY KEY,code TEXT UNIQUE,type TEXT,title TEXT,description TEXT,category TEXT,service_id INTEGER,structure TEXT,priority TEXT,status TEXT,requester_id INTEGER,assignee_id INTEGER,created_by INTEGER,created_at TEXT,due_at TEXT,resolved_at TEXT,closed_at TEXT, resolution_note TEXT, unit_id INTEGER);
CREATE TABLE timeline(id INTEGER PRIMARY KEY,ticket_id INTEGER,actor_id INTEGER,event_type TEXT,details TEXT,created_at TEXT);
CREATE TABLE users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password_hash TEXT,full_name TEXT,email TEXT,role TEXT,structure TEXT,sector TEXT,active INTEGER DEFAULT 1, failed INTEGER DEFAULT 0, locked_until TEXT, must_change INTEGER DEFAULT 0, can_infra INTEGER DEFAULT 0, phone TEXT, institution TEXT, duty TEXT, profile_done INTEGER DEFAULT 0, org_unit_id INTEGER, org_head INTEGER DEFAULT 0);
CREATE INDEX idx_task_events ON task_events(task_id);
CREATE INDEX ix_tk_status ON tickets(status,created_at);
CREATE INDEX ix_tk_assignee ON tickets(assignee_id,status);
CREATE INDEX ix_tk_requester ON tickets(requester_id);
CREATE INDEX ix_tk_due ON tickets(due_at);
CREATE INDEX ix_tk_service ON tickets(service_id);
CREATE INDEX ix_tl_ticket ON timeline(ticket_id,id);
CREATE INDEX ix_tasks_ticket ON tasks(ticket_id,status);
CREATE INDEX ix_ta_user ON task_assignees(user_id);
CREATE INDEX ix_steps_ticket ON ticket_steps(ticket_id,seq);
CREATE INDEX ix_steps_user ON ticket_steps(user_id,status);
CREATE INDEX ix_notif_user ON notifications(user_id,is_read,id);
CREATE TRIGGER audit_nu BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'audit është i pandryshueshëm'); END;
CREATE TRIGGER audit_nd BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'audit është i pandryshueshëm'); END;
CREATE INDEX ix_cards_b ON cards(board_id,list_id);
CREATE INDEX ix_cards_a ON cards(assignee_id);
CREATE INDEX ix_boards_t ON boards(team_id);
CREATE INDEX ix_chat_to ON chat_messages(to_id,id);
CREATE INDEX ix_chat_pair ON chat_messages(from_id,to_id,id);
COMMIT;

